package com.tutorhub.review.controller;import com.tutorhub.common.security.CurrentUser;import com.tutorhub.review.dto.ReviewRequest;import com.tutorhub.review.service.ReviewService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class ReviewController {private final ReviewService s;private final CurrentUser c;public ReviewController(ReviewService s,CurrentUser c){this.s=s;this.c=c;}@PostMapping("/bookings/{id}/review")@ResponseStatus(HttpStatus.NO_CONTENT)void create(@PathVariable Long id,@Valid@RequestBody ReviewRequest r){s.create(c.require(),id,r);}@PostMapping("/reviews/{id}/reply")@ResponseStatus(HttpStatus.NO_CONTENT)void reply(@PathVariable Long id,@RequestBody Map<String,String> b){s.reply(c.require(),id,b.get("reply"));}}
